  "summary": "The code suffered from critical security vulnerabilities due to hardcoded credentials and performance issues caused by unpooled database connections. The refactored code implements environment variable-based configuration, a connection pool for resource efficiency, and improved documentation/type safety.",
  "fixed_code": "import os\nimport psycopg2\nfrom psycopg2 import pool\nfrom typing import List, Tuple\n\n# Configuration managed via environment variables\nDB_CONFIG = {\n    \"host\": os.getenv(\"DB_HOST\", \"db.internal.example.com\"),\n    \"user\": os.getenv(\"DB_USER\", \"reports\"),\n    \"password\": os.getenv(\"DB_PASSWORD\"),\n    \"dbname\": \"reports\",\n    \"sslmode\": \"verify-full\",\n    \"sslrootcert\": \"/path/to/ca.crt\"\n}\n\n# Initialize connection pool\nconnection_pool = psycopg2.pool.ThreadedConnectionPool(1, 10, **DB_CONFIG)\n\ndef monthly_totals(month: str) -> List[Tuple[str, float]]:\n    \"\"\"Retrieves total sales per team for a given month.\"\"\"\n    if not isinstance(month, str) or len(month) != 7: # Basic validation\n        raise ValueError(\"Invalid month format\")\n        \n    conn = connection_pool.getconn()\n    try:\n        with conn, conn.cursor() as cur:\n            cur.execute(\"SELECT team, SUM(total) FROM sales WHERE month = %s GROUP BY team\", (month,))\n            return cur.fetchall()\n    finally:\n        connection_pool.putconn(conn)"
}
